; ---------------------------------------------------------------
; CHAT - the Claude chat terminal, 6809.
; Written for CLOADM. Dragon 32/64/200, Tano, Color Computer 1/2/2B
; and clones: a 256x192 two-colour VDG screen (GM7) with this
; project's own 6x8 font (examples/chat-font.inc, generated by
; tools/chat-font.js): 42 columns, 24 rows, lowercase and uppercase.
;
; It replaces BASIC: boots to a prompt, echoes what you type (up to
; 255 characters, wrapped as you type the way replies wrap: a word that
; does not fit moves to the next line; BACKSPACE goes back across the
; wraps; a key past the limit flashes the screen instead of being
; taken; keys typed while a reply comes wait in a type-ahead ring,
; TABUF, and are typed once the prompt is back), sends
; each line over the byte channel to the chat backend, shows
; "Thinking...", and displays the reply as bytes arrive. Replies wrap
; at a word boundary; a word longer than a whole line is broken at 42
; columns; a full screen scrolls one row. Lowercase is drawn from the
; font, so it needs no inverted-video trick and no ROM.
;
; The channel is a narrow byte seam (js/claude/channel.js), carried one
; of two ways, chosen at start:
;  - DriveWire on a Becker port ($FF41 status, bit 1 = a byte waits;
;    $FF42 data), as an emulated CoCo with the Becker port option or a
;    real machine with one: DWPROBE sends DWINIT and, if a server answers,
;    opens virtual serial channel DWCH (SERINIT). Typed bytes go out with
;    FASTWRITE; the reply comes in with SERREAD / SERREADM into RXBUF, a
;    256-byte ring (DriveWire 4 specification, "Virtual Serial
;    Channels"). A port that shows a byte waiting before anything was
;    asked, or that does not answer, is not a Becker port.
;  - otherwise the page's mailbox: RXSTAT at $7000 (bit 7 = a byte waits
;    in RXDATA at $7001), TXSTAT at $7002 (bit 7 = a byte for the backend
;    in TXDATA at $7003); the page fills RX and takes TX each frame.
; Keys come from the ROM's POLCAT vector, so it runs on the stub firmware
; or with BASIC ROMs.
;
; Screen geometry (GM7): 32 bytes a line x 192 lines; each byte is 8
; pixels, so a line is 256 pixels. A glyph is 6 pixels wide and 8 tall,
; at column c starting at pixel c*6: 42 columns fill 252 pixels.
;
; Build: node tools/build-examples.js  (examples/chat.bin)
; ---------------------------------------------------------------

POLCAT  EQU     $A000           ; ROM vector: read key -> A, Z=1 if none
SCREEN  EQU     $0400
COLS    EQU     42
ROWS    EQU     24
GLYPH_H EQU     8
GLYPH_W EQU     6
FONT1ST EQU     32
BSTAT   EQU     $FF41           ; Becker port: status (bit 1 = data waiting)
BDATA   EQU     $FF42           ; Becker port: data
DWCH    EQU     14              ; the DriveWire channel the chat uses (js/claude/channel.js CHAT_DW_CHANNEL)
DWWAITN EQU     64              ; main-loop passes between two SERREADs while nothing is buffered

        ORG     $6000
CHAT    JMP     START
        ORG     $6010
CURROW  FCB     0               ; row the next laid-out line goes to
LLEN    FCB     0               ; characters in LBUF
LASTSP  FCB     $FF             ; index of the last space in LBUF ($FF = none)
BLEN    FCB     0               ; characters typed on the input line
OLDLEN  FCB     0
OLDEND  FCB     0               ; WRAP: the full length before the break
OLDSP   FCB     0               ; WRAP: the break index, kept across FLUSHAT
FBYTE   FCB     0               ; DRAWCHAR: first screen byte of the glyph
FSHIFT  FCB     0               ; DRAWCHAR: g << (10-o), where o = (col*6) & 7
FHI     FCB     0               ; DRAWCHAR: mask for the first byte's low bits
FLO     FCB     0               ; DRAWCHAR: mask for the second byte's high bits
FCHR    FCB     0               ; DRAWCHAR: glyph index (char - 32)
FCOL    FCB     0               ; DRAWCHAR: column
ECOL    FCB     0               ; ECHO: cursor column on the typing line
SPOS    FCB     0               ; SENDNEXT: byte index in IBUF
SLEN    FCB     0               ; SENDNEXT: the line length (0-255)
SPEND   FCB     0               ; SENDNEXT: a line is queued (its bytes, then the CR); a flag, since 255 + CR is 256
FLINE   FCB     0               ; DRAWCHAR: pixel line of this glyph row
; DRAWCHAR scratch, kept in the direct page so plain (direct-mode) LDA/STA reach it
G       FCB     0
HI      FCB     0
LO      FCB     0
TMPO    FCB     0
TMPS    FCB     0
TCOL    FCB     0
TEMP    FCB     0
TLINE   FCB     0               ; DRAWCHAR: first pixel line of the row
GLYPH   RMB     8               ; DRAWCHAR: the 8 rows of the glyph being drawn
TROW    FCB     0               ; the typed line: its screen row now (0 = the prompt's row)
RCOL0   FCB     0               ; the typed line: the column its first character is on (after the prompt)
TRS     FCB     0               ; TWRAP/BACK/COLOF: RSTART of the row
TNEW    FCB     0               ; TWRAP: index of the character that did not fit
TWS     FCB     0               ; TWRAP: index of the first character of the word moved down
WAIT    FCB     0               ; a line was sent and its reply has not ended ($04): typing waits
PREVCR  FCB     0               ; the last reply byte was CR (an LF after it ends no second line)
        ORG     $7000
RXSTAT  FCB     0
RXDATA  FCB     0
TXSTAT  FCB     0
TXDATA  FCB     0
DWMODE  FCB     0               ; $FF: DriveWire on the Becker port; 0: the mailbox
RXHEAD  FCB     0               ; RXBUF: next byte to take
RXTAIL  FCB     0               ; RXBUF: next free place
DWWAIT  FCB     0               ; passes left before the next SERREAD
DWCNT   FCB     0               ; SERREADM: bytes to read
TAHEAD  FCB     0               ; TABUF: next key to take
TATAIL  FCB     0               ; TABUF: next free place (TAHEAD = TATAIL: nothing typed ahead)
        ORG     $7100
RXBUF   RMB     256
TABUF   RMB     256             ; keys typed, taken in order once the prompt is back (255 at most: one place stays free)
        ORG     $6040
LBUF    RMB     48
IBUF    RMB     255             ; the typed line: up to 255 characters (BLEN, SLEN and SPOS are bytes)
RSTART  RMB     16              ; the typed line: IBUF index of the first character on each of its screen rows

START   ORCC    #$50
        LDS     #$6000
        CLR     RXSTAT
        CLR     RXDATA
        CLR     TAHEAD          ; nothing typed ahead
        CLR     TATAIL
        JSR     DWPROBE
        JSR     GM7
        LDX     #PROMPT
        JSR     PUTC
        CLR     BLEN
        CLR     WAIT
        CLR     PREVCR

; ---------------- main loop ----------------
MAIN    JSR     SENDNEXT        ; a pending line goes out one byte per pass; never waits on the page
        JSR     [POLCAT]
        TSTA
        BEQ     MAINK
        ; every key goes into the type-ahead ring, so one typed while a reply comes is kept, not dropped: it is
        ; taken once the prompt is back, in the order typed. BREAK while a reply comes is the page's (it stops
        ; the reply), so it is not kept for the next line.
        TST     WAIT
        BEQ     MAINQ
        CMPA    #3
        BEQ     MAIN2
MAINQ   LDB     TATAIL
        INCB
        CMPB    TAHEAD
        LBEQ    FULL            ; the ring is full: refused visibly, as a key past the 255th is
        LDX     #TABUF
        LDB     TATAIL
        ABX                     ; (unsigned: B,X would go backwards from the 128th place)
        STA     ,X
        INC     TATAIL
MAINK   TST     WAIT            ; while a reply comes, typed keys wait in the ring
        BNE     MAIN2
        LDB     TAHEAD
        CMPB    TATAIL
        BEQ     MAIN2           ; nothing typed
        LDX     #TABUF
        ABX
        LDA     ,X
        INC     TAHEAD
        CMPA    #13
        LBEQ    ENTER
        CMPA    #8
        LBEQ    BACK
        CMPA    #$03
        LBEQ    BREAK
        CMPA    #32
        BLO     MAIN2
        LDB     BLEN
        CMPB    #255
        LBHS    FULL            ; the line is full: say so, don't drop the key silently
        TSTB
        BNE     TYP1
        CLR     TROW            ; the line's first character: its first row starts here, after the prompt
        CLR     RSTART
        LDB     ECOL
        STB     RCOL0
        CLRB
TYP1    LDX     #IBUF
        ABX
        STA     ,X
        INC     BLEN
        LDB     ECOL
        CMPB    #COLS
        BLO     TYP2
        JSR     TWRAP           ; the row is full: the line goes on on the next row (carry: nothing to draw)
        BCS     MAIN2
TYP2    JSR     ECHO            ; typed text shows at once
MAIN2   JSR     POLLCH
        LBEQ    MAIN
        CMPA    #4
        BEQ     MAINEOT
        CMPA    #13
        BEQ     MAINCR
        CMPA    #10
        BEQ     MAINLF
        CLR     PREVCR
        CMPA    #32
        LBLO    MAIN
        JSR     OUTCH           ; reply text is laid out and wrapped
        LBRA    MAIN
MAINCR  JSR     FLUSHLINE
        LDA     #1
        STA     PREVCR
        LBRA    MAIN
MAINLF  TST     PREVCR          ; CR LF ends one line, not two
        BNE     MAINLF2
        JSR     FLUSHLINE
MAINLF2 CLR     PREVCR
        LBRA    MAIN
; $04: the reply has ended. Its last line is laid out, and a fresh prompt takes typing again
MAINEOT LDA     LLEN
        BEQ     MEOT1
        JSR     FLUSHLINE
MEOT1   CLR     ECOL
        LDX     #PROMPT
        JSR     PUTC
        CLR     WAIT
        CLR     PREVCR
        LBRA    MAIN

; TWRAP: the character A (just stored at IBUF[BLEN-1]) does not fit on the full row. As replies wrap: a space ends
; the row and is not drawn (carry set: nothing to draw); otherwise the row's last word, after its last space, moves
; to the start of the next row; a row with no space breaks at the character. RSTART gets the new row's start.
TWRAP   CMPA    #32
        BNE     TW1
        JSR     TNEXT
        LDB     BLEN            ; the next row starts after the space
        JSR     SETRS
        ORCC    #1
        RTS
TW1     PSHS    A
        JSR     GETRS
        STB     TRS
        LDB     BLEN
        DECB
        STB     TNEW
TW2     CMPB    TRS             ; look back for the row's last space
        BLS     TWCH
        DECB
        LDX     #IBUF
        ABX
        LDA     ,X
        CMPA    #32
        BNE     TW2
        INCB                    ; B = the first character after it
        STB     TWS
TW3     CMPB    TNEW            ; rub the word out on this row
        BHS     TW4
        PSHS    B
        JSR     COLOF
        STB     ECOL
        LDA     #32
        JSR     ECHO
        PULS    B
        INCB
        BRA     TW3
TW4     JSR     TNEXT
        LDB     TWS
        JSR     SETRS
TW5     CMPB    TNEW            ; and draw it at the start of the next
        BHS     TW6
        PSHS    B
        LDX     #IBUF
        ABX
        LDA     ,X
        JSR     ECHO
        PULS    B
        INCB
        BRA     TW5
TW6     PULS    A
        ANDCC   #$FE
        RTS
TWCH    JSR     TNEXT           ; no space: break at the character
        LDB     TNEW
        JSR     SETRS
        PULS    A
        ANDCC   #$FE
        RTS
; TNEXT: the typed line goes on on the next row
TNEXT   CLR     ECOL
        JSR     NEXTROW
        INC     TROW
        RTS
; SETRS: RSTART[TROW] = B (B kept); GETRS: B = RSTART[TROW]
SETRS   PSHS    B
        LDX     #RSTART
        LDB     TROW
        ABX
        PULS    B
        STB     ,X
        RTS
GETRS   LDX     #RSTART
        LDB     TROW
        ABX
        LDB     ,X
        RTS
; COLOF: B = the column of typed character B on row TROW
COLOF   PSHS    B
        JSR     GETRS
        STB     TRS
        PULS    B
        SUBB    TRS
        TST     TROW
        BNE     COL1
        ADDB    RCOL0
COL1    RTS

; FULL: a key past the 255th character is refused visibly: the screen flashes (CSS set: green becomes buff) for
; about a tenth of a second (12000 passes of an 8-cycle loop at 0.89 MHz), then comes back
FULL    LDA     #$F8            ; A/G=1, GM=7, CSS=1
        STA     $FF22
        LDX     #12000
FULL1   LEAX    -1,X
        BNE     FULL1
        LDA     #$F0            ; CSS=0 again
        STA     $FF22
        LBRA    MAIN2

; Enter: queue the typed line (it goes out a byte at a time from the main loop), then show the wait; the
; next prompt comes when the reply ends ($04 from the page). An empty line is not sent.
ENTER   LDA     BLEN
        LBEQ    MAIN
        JSR     NEWLINE         ; the typed line is done
        LDA     #1
        STA     WAIT
        CLR     ECOL
        LDX     #THINK
        JSR     PUTC
        JSR     NEWLINE         ; and the reply starts below it
        ; queue the line's bytes and the CR: SPOS = next byte to send, SPEND = something is queued
        CLR     SPOS
        LDA     BLEN
        STA     SLEN            ; the line's length (the CR follows it)
        LDA     #1
        STA     SPEND
        CLR     BLEN
        LBRA    MAIN

; SENDNEXT: if a line is queued and the page has taken the last byte, hand over the next one
SENDNEXT
        LDA     SPEND
        BEQ     SNX             ; nothing queued
        TST     DWMODE
        BNE     SN0             ; (DriveWire: the server takes each byte as it is written)
        LDA     TXSTAT
        ANDA    #$80
        BNE     SNX             ; the page has not taken the last byte yet
SN0     LDB     SPOS
        CMPB    SLEN
        BLO     SNC1
        LDA     #13             ; past the line: the CR, the last byte
        CLR     SPEND
        BRA     SNC2
SNC1    LDX     #IBUF
        ABX                     ; (unsigned: LEAX A,X would go backwards from the 128th character)
        LDA     ,X
        INC     SPOS
SNC2    TST     DWMODE
        BNE     SNDW
        STA     TXDATA
        LDA     #$80
        STA     TXSTAT
        RTS
SNDW    LDB     #$80+DWCH       ; FASTWRITE on channel DWCH, then the byte
        STB     BDATA
        STA     BDATA
SNX     RTS

BACK    LDB     BLEN
        LBEQ    MAIN
        DECB
        STB     BLEN            ; B = index of the character taken back
        TST     TROW
        BEQ     BK1
        PSHS    B
        JSR     GETRS
        STB     TRS
        PULS    B
        CMPB    TRS
        BHS     BK1             ; it is on this row: rub it out where it is
        DEC     TROW            ; it is on the row above (this row is empty): go back there
        DEC     CURROW
        JSR     COLOF
        STB     ECOL
        CMPB    #COLS
        LBHS    MAIN            ; a space that ended a full row was never drawn
        LDA     #32
        JSR     ECHO
        DEC     ECOL
        LBRA    MAIN
BK1     LDA     #8
        JSR     ECHO
        LDA     #32
        JSR     ECHO
        LDA     #8
        JSR     ECHO
        LBRA    MAIN

BREAK   JSR     FLUSHLINE       ; what was typed is dropped, and a fresh prompt starts
        CLR     BLEN
        CLR     ECOL
        LDX     #PROMPT
        JSR     PUTC
        LBRA    MAIN

; ---------------------------------------------------------------
POLLCH  TST     DWMODE
        BNE     PDW
        LDA     RXSTAT
        ANDA    #$80
        BEQ     POLLN
        CLR     RXSTAT
        LDA     RXDATA
        RTS
POLLN   CLRA
        RTS
; DriveWire: a buffered byte, or ask the server now and then
PDW     LDA     RXHEAD
        CMPA    RXTAIL
        BNE     PDW3
        JSR     DWREAD
        LDA     RXHEAD
        CMPA    RXTAIL
        BEQ     POLLN
PDW3    LDB     RXHEAD
        INC     RXHEAD
        LDX     #RXBUF
        ABX
        LDA     ,X              ; (sets Z as the mailbox path does)
        RTS

; ---------------------------------------------------------------
; DriveWire on the Becker port
; ---------------------------------------------------------------
; DWPROBE: DWINIT; an answer means a server: open channel DWCH (SERINIT) and use it
DWPROBE CLR     DWMODE
        CLR     RXHEAD
        CLR     RXTAIL
        LDA     #1
        STA     DWWAIT
        LDA     BSTAT
        BITA    #$02
        BNE     DWPX            ; a byte "waiting" before anything was asked: not a Becker port
        LDA     #$5A            ; OP_DWINIT, then our version byte
        STA     BDATA
        LDA     #$01
        STA     BDATA
        JSR     DWGET
        BCS     DWPX            ; no answer: the mailbox
        LDA     #$FF
        STA     DWMODE
        LDA     #$45            ; OP_SERINIT DWCH
        STA     BDATA
        LDA     #DWCH
        STA     BDATA
DWPX    RTS

; DWREAD: every DWWAITN calls, SERREAD; a byte for DWCH goes to RXBUF, and when several wait, SERREADM takes as
; many as RXBUF has room for
DWREAD  DEC     DWWAIT
        BNE     DWRX
        LDA     #DWWAITN
        STA     DWWAIT
        LDA     #$43            ; OP_SERREAD
        STA     BDATA
        JSR     DWGET
        TFR     A,B             ; B = response byte 1
        JSR     DWGET           ; A = response byte 2
        CMPB    #DWCH+1
        BEQ     RXPUT           ; one byte for DWCH
        CMPB    #DWCH+17
        BEQ     DWRM            ; A bytes wait on DWCH
DWRX    RTS
DWRM    STA     DWCNT
        LDA     RXTAIL
        SUBA    RXHEAD          ; bytes in RXBUF
        NEGA
        DECA                    ; room: 255 - that
        CMPA    DWCNT
        BHS     DWRM1
        STA     DWCNT
DWRM1   LDA     DWCNT
        BEQ     DWRX
        LDA     #$63            ; OP_SERREADM DWCH count
        STA     BDATA
        LDA     #DWCH
        STA     BDATA
        LDA     DWCNT
        STA     BDATA
DWRM2   JSR     DWGET
        JSR     RXPUT
        DEC     DWCNT
        BNE     DWRM2
        RTS
; RXPUT: A into RXBUF
RXPUT   LDB     RXTAIL
        INC     RXTAIL
        LDX     #RXBUF
        ABX
        STA     ,X
        RTS
; DWGET: the next byte from the server in A (carry clear), or carry set after about half a second of nothing
DWGET   LDX     #20000
DWG1    LDA     BSTAT
        BITA    #$02
        BNE     DWG2
        LEAX    -1,X
        BNE     DWG1
        CLRA
        COMA                    ; (sets carry)
        RTS
DWG2    LDA     BDATA
        ANDCC   #$FE
        RTS

; NEWLINE: end the typing line and start a fresh one
NEWLINE CLR     ECOL
        JSR     NEXTROW
        RTS

; ---------------------------------------------------------------
; ECHO: draw one character at the current cursor (CURROW row, ECOL column). Typed text and fixed strings use
; this; past column 42 a string goes on at the start of the next row (the typed line wraps itself first: TWRAP).
; Control codes move the cursor: 8 backspace (within the row), 32+ a glyph.
; ---------------------------------------------------------------
ECHO    CMPA    #8
        BEQ     ECHOBS
        LDB     ECOL
        CMPB    #COLS
        BLO     ECHO1
        CLR     ECOL            ; past the last column: continue on the next row
        JSR     NEXTROW
ECHO1   PSHS    A               ; keep the character: setting TLINE uses A
        LDA     CURROW
        LDB     #GLYPH_H
        MUL
        STB     TLINE           ; DRAWCHAR draws on this row
        PULS    A
        LDB     ECOL
        JSR     DRAWCHAR
        INC     ECOL
        RTS
ECHOBS  LDB     ECOL
        BEQ     ECHOR
        DECB
        STB     ECOL
        PSHS    A
        LDA     CURROW
        LDB     #GLYPH_H
        MUL
        STB     TLINE
        PULS    A
        LDA     #32             ; rub the character off with a space
        LDB     ECOL
        JSR     DRAWCHAR
ECHOR   RTS
OUTCH   CMPA    #8
        BEQ     OUTCBS
        CMPA    #32
        BNE     OUTC1
        JSR     SPACE
        RTS
OUTCBS  LDB     LLEN
        BEQ     OUTC9
        DECB
        STB     LLEN
        ; a removed space is no longer a break point: forget it
        CMPB    LASTSP
        BNE     OUTC9
        LDA     #$FF
        STA     LASTSP
OUTC9   RTS
OUTC1   LDB     LLEN
        CMPB    #COLS
        BLO     OUTC2
        PSHS    A               ; WRAP lays out the buffer and leaves A = a count: keep the character
        JSR     WRAP
        PULS    A
        LDB     LLEN
OUTC2   LDX     #LBUF
        ABX
        STA     ,X
        INC     LLEN
        RTS

SPACE   LDB     LLEN
        BEQ     SPACE2
        CMPB    #COLS
        BLO     SPACE1
        JSR     FLUSHLINE
        RTS
SPACE1  LDX     #LBUF
        ABX
        LDA     #32
        STA     ,X
        STB     LASTSP
        INC     LLEN
SPACE2  RTS

; WRAP: the buffer is full and a non-space arrived.
; With a break point: flush up to it and carry the tail down.
; Without one (a word longer than a line): flush all COLS characters.
WRAP    LDA     LASTSP
        CMPA    #$FF
        BNE     WRAP1
        JSR     FLUSHLINE
        RTS
WRAP1   ; FLUSHAT draws OLDLEN characters and clears LLEN, so OLDLEN (not LLEN) is what selects the
        ; break point. Keep the full length for the tail move.
        LDA     LLEN
        STA     OLDEND
        LDA     LASTSP
        STA     OLDSP           ; FLUSHAT clears LASTSP, so keep the break index for the tail
        STA     OLDLEN          ; draw up to the space
        JSR     FLUSHAT
        ; move LBUF[OLDSP+1 .. OLDEND) to the front
        LDA     OLDSP
        INCA
        LDX     #LBUF
        LEAX    A,X
        LDY     #LBUF
        CLR     LLEN
TAIL    LDA     LLEN
        ADDA    OLDSP
        INCA
        CMPA    OLDEND
        BHS     TAILD
        LDA     ,X+
        STA     ,Y+
        INC     LLEN
        BRA     TAIL
TAILD   LDA     #$FF
        STA     LASTSP
        RTS

; FLUSHLINE: draw LBUF[0..LLEN) at CURROW, then the next row
FLUSHLINE LDA     LLEN
        STA     OLDLEN
FLUSHAT CLR     LLEN
        LDA     #$FF
        STA     LASTSP
        LDA     CURROW
        LDB     #GLYPH_H
        MUL                     ; D = first pixel line of the row
        STB     TLINE
        CLR     TCOL
FL1     LDB     TCOL
        CMPB    OLDLEN
        BHS     FLDONE
        LDA     TCOL
        LDX     #LBUF
        LEAX    A,X             ; X = &LBUF[TCOL]
        LDA     ,X              ; the character
        ; B is still TCOL: the column
        JSR     DRAWCHAR        ; (TLINE holds the row's first pixel line)
        INC     TCOL
        BRA     FL1
FLDONE  JSR     NEXTROW
        RTS

; ---------------------------------------------------------------
; DRAWCHAR: draw the character in A at column B, first pixel line Y.
; Glyph row g (6 bits, bit 5 leftmost) at pixel line Y+r:
;   pixel p = B*6, byte b = p>>3, o = p&7 (0,2,4,6)
;   V = g << (10-o);  store (b & ~hiMask) | (V>>8 & hiMask)
;                     store (b+1 & ~loMask) | (V & loMask)
; hiMask and loMask are the bits V actually fills (from the 6-bit glyph).
; ---------------------------------------------------------------
DRAWCHAR
        PSHS    A,B,X,Y,U
        STA     FCHR
        STB     FCOL
        JSR     FSETUP
        ; glyph -> GLYPH: FONT + (char-32)*8; the product exceeds 255 (33*8 = 264), so 16-bit
        LDA     FCHR
        SUBA    #FONT1ST
        TFR     A,B
        CLRA                    ; D = index
        LSLB
        ROLA
        LSLB
        ROLA
        LSLB
        ROLA                    ; D = index*8
        ADDD    #FONT
        TFR     D,X             ; X = &FONT[index*8]
        LDU     #GLYPH
        LDB     #GLYPH_H
GL1     LDA     ,X+
        STA     ,U+
        DECB
        BNE     GL1
        ; rows
        CLR     FLINE
        LDU     #GLYPH
ROWLP   LDA     FLINE
        CMPA    #GLYPH_H
        BHS     CLRDONE
        LDA     ,U+             ; g
        JSR     PLACE           ; place g on pixel line (TLINE + FLINE)
        INC     FLINE
        BRA     ROWLP
CLRDONE PULS    U,Y,X,B,A
        RTS

; FSETUP: from FCOL, set FBYTE, FSHIFT, FHI, FLO.
;   p = FCOL*6 (<= 246, so one byte); FBYTE = p>>3; o = p&7; FSHIFT = 10-o
;   V = 0x3F << FSHIFT, a 16-bit value; FHI = V>>8 (the bits landing in byte b),
;   FLO = V&0xFF (the bits landing in byte b+1)
FSETUP  LDA     FCOL
        LDB     #GLYPH_W
        MUL                     ; B = p = FCOL*6 (A is 0: p < 256)
        STB     TMPS
        ANDB    #7              ; o = p & 7
        STB     TMPO
        LDA     #10
        SUBA    TMPO
        STA     FSHIFT          ; FSHIFT = 10 - o  (4, 6, 8 or 10)
        LDA     TMPS
        LSRA
        LSRA
        LSRA                    ; p >> 3
        STA     FBYTE
        ; V = 0x3F << FSHIFT, built in HI:LO (two bytes; a 16-bit store would spill)
        LDA     #$3F
        STA     LO              ; LO = 0x3F
        CLR     HI              ; HI = 0 (a byte, so it cannot touch LO)
        LDB     FSHIFT
FS2     CMPB    #0
        BEQ     FS3
        ; 16-bit left shift of HI:LO
        LSL     LO
        ROL     HI
        DECB
        BRA     FS2
FS3     LDA     HI
        STA     FHI
        LDA     LO
        STA     FLO
        RTS

; PLACE: put glyph row g (in A) at pixel line FLINE using FBYTE/FSHIFT/FHI/FLO.
; The screen byte is at SCREEN + FLINE*32 + FBYTE; the row's 16-bit V (g <<
; FSHIFT) lands in that byte (low bits) and the next (high bits).
PLACE   PSHS    A,B,X,Y
        STA     G                 ; g
        ; screen address = SCREEN + (TLINE + FLINE)*32 + FBYTE.
        ; TLINE+FLINE is 0..191, so the low byte holds it and one 8x8 multiply is enough.
        LDA     TLINE
        ADDA    FLINE
        LDB     #32
        MUL
        ADDD    #SCREEN
        TFR     D,X
        LDB     FBYTE
        ABX                     ; X = the first screen byte
        ; V = g << FSHIFT, built in HI:LO (the same shift as FSETUP's mask)
        LDA     G
        STA     LO
        CLR     HI
        LDB     FSHIFT
PL2     CMPB    #0
        BEQ     PL3
        LSL     LO
        ROL     HI
        DECB
        BRA     PL2
PL3     ; byte b: keep everything but FHI, set (HI & FHI)
        LDA     FHI
        COMA
        ANDA    ,X
        STA     TEMP
        LDA     HI
        ANDA    FHI
        ORA     TEMP
        STA     ,X
        ; byte b+1: keep everything but FLO, set (LO & FLO)
        LDA     FLO
        COMA
        ANDA    1,X
        STA     TEMP
        LDA     LO
        ANDA    FLO
        ORA     TEMP
        STA     1,X
        PULS    Y,X,B,A
        RTS

; NEXTROW
NEXTROW INC     CURROW
        LDB     CURROW
        CMPB    #ROWS
        BLO     NRD
        JSR     SCROLL
        DEC     CURROW
NRD     RTS

; SCROLL: move rows 1..23 up one row and clear the last row. The copy loop compares X against the end of
; the screen: a 16-bit counter in D would be destroyed by LDA ,X+, which loads the high half of D.
SCROLL  LDX     #SCREEN+256
        LDY     #SCREEN
SC1     LDA     ,X+
        STA     ,Y+
        CMPX    #SCREEN+(ROWS)*256
        BNE     SC1
        LDX     #SCREEN+(ROWS-1)*256
        LDB     #0
        LDA     #0
SC2     STA     ,X+
        DECB
        BNE     SC2
        RTS

CLS     LDX     #SCREEN
        LDD     #0
CL1     STD     ,X++
        CMPX    #SCREEN+6144
        BNE     CL1
        RTS

; GM7: 256x192 two-colour, PIA1 port B bits 3-7 = the VDG mode lines
; (PB7 A/G, PB6-4 GM2-0, PB3 CSS), and the SAM in the matching mode:
; V2-V0 = 110 (6K graphics) with the display at $0400 (F6-F0 = 2), set
; bit by bit through the SAM's clear/set address pairs, and its memory
; size to 64K (M1-M0 = 10, as BASIC sets it).
GM7     LDA     #$30
        STA     $FF23
        LDA     #$FE
        STA     $FF22
        LDA     #$34
        STA     $FF23
        LDA     #$F0            ; A/G=1, GM=7, CSS=0 (green / black)
        STA     $FF22
        STA     $FFC0           ; V0 = 0
        STA     $FFC3           ; V1 = 1
        STA     $FFC5           ; V2 = 1
        STA     $FFC6           ; F0 = 0
        STA     $FFC9           ; F1 = 1   ($0400 = 2 x 512)
        STA     $FFCA           ; F2 = 0
        STA     $FFCC           ; F3 = 0
        STA     $FFCE           ; F4 = 0
        STA     $FFD0           ; F5 = 0
        STA     $FFD2           ; F6 = 0
        STA     $FFDA           ; M0 = 0
        STA     $FFDD           ; M1 = 1   (64K: at 4K the display address wraps at
                                ;          $1000; the chat uses $0400-$7FFF,
                                ;          so 32K or more)
        JSR     CLS
        CLR     CURROW
        CLR     LLEN
        LDA     #$FF
        STA     LASTSP
        RTS

; PUTC: print the NUL-terminated string at X. OUTCH uses X, so the string pointer is saved
; around each call.
PUTC    LDA     ,X+
        BEQ     PUTCD
        PSHS    X
        JSR     ECHO
        PULS    X
        BRA     PUTC
PUTCD   RTS

TEMP0   FCB     0
PROMPT  FCC     "> "
        FCB     0
THINK   FCC     "Thinking..."
        FCB     13,0

FONT
        INCLUDE "chat-font.inc"

        END     START
